import js from "@eslint/js";
import { defineConfig, globalIgnores } from "eslint/config";
import globals from "globals";
import tseslint from "typescript-eslint";

export default defineConfig([
  // apps/desktop/src/bindings.ts is generated by tauri-specta; tsc checks it and a test keeps it fresh.
  globalIgnores(["apps/desktop/src/bindings.ts", "**/dist/", "**/node_modules/", "target/", ".dev-data/", "apps/desktop/src-tauri/", "python/", "docs/", "**/web/vendor/", "tests/e2e/out/"]),
  js.configs.recommended,
  tseslint.configs.recommended,
  { files: ["**/*.mjs", "**/*.js", "apps/desktop/vite.config.ts"], languageOptions: { globals: globals.node } },
  // The render spike's page runs in a webview, and the E2E specs in WebdriverIO's runner.
  { files: ["tests/spikes/headless-render/web/*.js"], languageOptions: { globals: globals.browser } },
  // Functions passed to browser.execute run in the app's webview, so the E2E files see both sets of globals.
  {
    files: ["tests/e2e/**/*.mjs"],
    languageOptions: { globals: { ...globals.node, ...globals.browser, ...globals.mocha, browser: "readonly" } },
  },
  // The viewer is plain TypeScript with no UI framework inside it (plan section 06).
  {
    files: ["packages/viewer/**/*.ts"],
    rules: { "no-restricted-imports": ["error", { patterns: [{ group: ["react", "react-*", "react/*"], message: "The viewer has no React inside it (plan section 06)." }] }] },
  },
]);
